#include <stdio.h>

int x[6];

int main(void) {
    int s = 0;
    for (int i = 0; i < 6; i++) {
        scanf("%d", &x[i]);
        s += x[i];
    }
    if (s % 3 != 0) {
        printf("N\n");
        return 0;
    }
    int t = s / 3;
    for (int i = 0; i < 6; i++) {
        if (x[i] != t) continue; /* cubo do topo */
        int used[6] = {0};
        used[i] = 1;
        for (int j = 0; j < 6; j++) {
            if (used[j]) continue;
            for (int k = j + 1; k < 6; k++) {
                if (used[k]) continue;
                if (x[j] + x[k] == t) {
                    printf("S\n");
                    return 0;
                }
            }
        }
    }
    printf("N\n");
    return 0;
}
